const key='muspec-language',values=new WeakMap();
let language='th';try{language=localStorage.getItem(key)==='en'?'en':'th'}catch{}
export const getLanguage=()=>language;
export function t(key,params={}){const text=messages[key]?.[language==='en'?1:0]??key;return text.replace(/\{(\w+)\}/g,(_,name)=>String(params[name]??''))}
export function setText(el,key,params={}){el.dataset.i18n=key;values.set(el,params);el.textContent=t(key,params)}
export function translate(root=document){
 for(const el of root.querySelectorAll('[data-i18n]'))el.textContent=t(el.dataset.i18n,values.get(el));
 for(const [attr,data] of [['aria-label','i18nAria'],['title','i18nTitle'],['placeholder','i18nPlaceholder']])for(const el of root.querySelectorAll(`[data-${data.replace(/[A-Z]/g,m=>'-'+m.toLowerCase())}]`))el.setAttribute(attr,t(el.dataset[data]));
 document.documentElement.lang=language;
 for(const button of document.querySelectorAll('[data-language]'))button.setAttribute('aria-pressed',String(button.dataset.language===language));
}
export function setLanguage(next,persist=true){if(!['th','en'].includes(next))return;const changed=next!==language;language=next;if(persist)try{localStorage.setItem(key,next)}catch{}translate();if(changed)window.dispatchEvent(new CustomEvent('lab-language-change',{detail:{language}}))}
export function initLanguage(){translate();for(const button of document.querySelectorAll('[data-language]'))button.disabled=false;document.addEventListener('click',e=>{const button=e.target.closest('[data-language]');if(button)setLanguage(button.dataset.language)});window.addEventListener('storage',e=>{if(e.key===key)setLanguage(e.newValue,false)})}
